-- supabase-fhir | single-file distribution
-- Generated by scripts/build-sql.ts from:
--   20261113000001_fhir_core.sql
--   20261113000002_fhir_access.sql
--   20261113000003_fhir_define_resource.sql
--   20261113000004_fhir_resources.sql
--   20261113000005_fhir_api.sql
