-- =============================================================================
-- supabase-fhir | 0001 core
-- Schema, helper functions, resource type registry, version history,
-- audit log and the trigger functions shared by every resource table.
-- =============================================================================

create schema if not exists fhir;
comment on schema fhir is
  'FHIR R4 resources stored as JSONB with patient-compartment RLS, version history and audit log.';

-- Fail closed: anonymous clients never see this schema.
revoke all on schema fhir from public;
grant usage on schema fhir to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Helper functions
-- All of them are IMMUTABLE so they can back generated columns and indexes.
-- -----------------------------------------------------------------------------

-- 'MedicationRequest' -> 'medication_request'
create or replace function fhir.table_name(resource_type text)
returns text
language sql immutable strict parallel safe
set search_path = ''
as $$
  select lower(regexp_replace(resource_type, '([a-z0-9])([A-Z])', '\1_\2', 'g'));
$$;

-- fhir.reference_id('Patient/123', 'Patient') -> '123'
-- Accepts relative references, absolute URLs and versioned references.
-- Returns null for urn:uuid, conditional and foreign-type references.
create or replace function fhir.reference_id(reference text, resource_type text)
returns text
language sql immutable strict parallel safe
set search_path = ''
as $$
  select (regexp_match(
    reference,
    '(?:^|/)' || resource_type || '/([A-Za-z0-9\-\.]{1,64})(?:/_history/[^/]+)?$'
  ))[1];
$$;

-- The Patient compartment a resource belongs to, or null for resources that
-- are not about a single patient (Practitioner, Organization, ...).
create or replace function fhir.compartment_patient_id(resource jsonb)
returns text
language sql immutable strict parallel safe
set search_path = ''
as $$
  select case
    when resource ->> 'resourceType' = 'Patient' then resource ->> 'id'
    else coalesce(
      fhir.reference_id(resource #>> '{subject,reference}', 'Patient'),
      fhir.reference_id(resource #>> '{patient,reference}', 'Patient'),
      fhir.reference_id(resource #>> '{beneficiary,reference}', 'Patient'),
      (
        select fhir.reference_id(t ->> 'reference', 'Patient')
        from jsonb_array_elements(
          case when jsonb_typeof(resource -> 'target') = 'array'
               then resource -> 'target' else '[]'::jsonb end
        ) as t
        where fhir.reference_id(t ->> 'reference', 'Patient') is not null
        limit 1
      )
    )
  end;
$$;

-- FHIR dateTime/instant (including partial '2024' and '2024-03') -> timestamptz.
-- Interprets zone-less values as UTC. Returns null when unparsable.
create or replace function fhir.parse_datetime(value text)
returns timestamptz
language plpgsql immutable strict parallel safe
set search_path = ''
set timezone to 'UTC'
set datestyle to 'ISO, YMD'
as $$
begin
  return case
    when value ~ '^\d{4}$' then (value || '-01-01')::timestamptz
    when value ~ '^\d{4}-\d{2}$' then (value || '-01')::timestamptz
    else value::timestamptz
  end;
exception when others then
  return null;
end;
$$;

-- FHIR date (including partial values) -> date. Returns null when unparsable.
create or replace function fhir.parse_date(value text)
returns date
language plpgsql immutable strict parallel safe
set search_path = ''
set datestyle to 'ISO, YMD'
as $$
begin
  return case
    when value ~ '^\d{4}$' then (value || '-01-01')::date
    when value ~ '^\d{4}-\d{2}$' then (value || '-01')::date
    else left(value, 10)::date
  end;
exception when others then
  return null;
end;
$$;

-- timestamptz -> FHIR instant string in UTC ('2026-01-31T12:00:00.000Z')
create or replace function fhir.instant(value timestamptz)
returns text
language sql stable strict parallel safe
set search_path = ''
as $$
  select to_char(value at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
$$;

-- Role of the caller as seen by PostgREST ('authenticated', 'service_role', ...)
-- or the database role when called outside the API (migrations, psql, tests).
create or replace function fhir.actor_role()
returns text
language sql stable parallel safe
set search_path = ''
as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role'),
    current_user::text
  );
$$;

-- Request metadata PostgREST exposes as settings. Empty outside the API.
create or replace function fhir.request_context()
returns jsonb
language plpgsql stable parallel safe
set search_path = ''
as $$
declare
  headers jsonb;
begin
  begin
    headers := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    headers := null;
  end;
  return jsonb_strip_nulls(jsonb_build_object(
    'method', nullif(current_setting('request.method', true), ''),
    'path', nullif(current_setting('request.path', true), ''),
    'ip', headers ->> 'x-forwarded-for',
    'user_agent', headers ->> 'user-agent'
  ));
end;
$$;

grant execute on function
  fhir.table_name(text),
  fhir.reference_id(text, text),
  fhir.compartment_patient_id(jsonb),
  fhir.parse_datetime(text),
  fhir.parse_date(text),
  fhir.instant(timestamptz),
  fhir.actor_role(),
  fhir.request_context()
to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Registry of resource types that have a table (filled by fhir.define_resource)
-- -----------------------------------------------------------------------------
create table fhir.resource_type (
  resource_type text primary key
    constraint resource_type_format check (resource_type ~ '^[A-Z][A-Za-z]{1,63}$'),
  table_name    text not null unique,
  compartment   boolean not null default true,
  created_at    timestamptz not null default now()
);
comment on table fhir.resource_type is
  'Resource types with a backing table. compartment=true means rows are scoped to a Patient.';

alter table fhir.resource_type enable row level security;
create policy "resource types are readable" on fhir.resource_type
  for select to authenticated using (true);
grant select on fhir.resource_type to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Version history: every superseded or deleted version of every resource
-- -----------------------------------------------------------------------------
create table fhir.resource_history (
  history_id    bigint generated always as identity primary key,
  resource_type text not null,
  id            text not null,
  version_id    integer not null,
  resource      jsonb not null,
  patient_id    text,
  last_updated  timestamptz not null,
  updated_by    uuid,
  operation     text not null constraint resource_history_operation check (operation in ('update', 'delete')),
  recorded_at   timestamptz not null default now()
);
comment on table fhir.resource_history is
  'Prior versions of resources. operation=update means superseded, delete means removed.';
create index resource_history_resource_idx on fhir.resource_history (resource_type, id, version_id desc);
create index resource_history_patient_idx on fhir.resource_history (patient_id);

alter table fhir.resource_history enable row level security;
grant select on fhir.resource_history to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Audit log: who did what to which resource (no PHI payload, only identifiers)
-- -----------------------------------------------------------------------------
create table fhir.audit_log (
  id            bigint generated always as identity primary key,
  occurred_at   timestamptz not null default now(),
  action        text not null constraint audit_log_action
                check (action in ('create', 'read', 'update', 'delete', 'search', 'grant', 'grant_change', 'revoke')),
  resource_type text not null,
  resource_id   text constraint audit_log_resource_id check (action = 'search' or resource_id is not null),
  patient_id    text,
  version_id    integer,
  actor_id      uuid,
  actor_role    text,
  request       jsonb
);
comment on table fhir.audit_log is
  'Access trail. Writes and access grant changes are recorded by triggers; reads and searches through the fhir RPCs (read_resource, patient_everything, search_resources, log_access). Identifiers only, never the payload.';
create index audit_log_patient_idx on fhir.audit_log (patient_id, occurred_at desc);
create index audit_log_resource_idx on fhir.audit_log (resource_type, resource_id);
create index audit_log_actor_idx on fhir.audit_log (actor_id, occurred_at desc);

alter table fhir.audit_log enable row level security;
grant select on fhir.audit_log to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Trigger functions shared by every resource table
-- -----------------------------------------------------------------------------

-- Keeps id, version and meta in sync and stamps the actor.
create or replace function fhir.before_write()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  now_ts timestamptz := now();
  actor  uuid := auth.uid();
  meta   jsonb;
begin
  if new.resource is null or jsonb_typeof(new.resource) <> 'object' then
    raise exception 'resource must be a JSON object' using errcode = '22023';
  end if;

  if tg_op = 'INSERT' then
    new.id := coalesce(nullif(new.resource ->> 'id', ''), new.id, gen_random_uuid()::text);
    new.version_id := 1;
    new.created_at := now_ts;
    new.created_by := actor;
  else
    if new.id is distinct from old.id then
      raise exception 'resource id is immutable (% -> %)', old.id, new.id using errcode = '23514';
    end if;
    if nullif(new.resource ->> 'id', '') is not null and new.resource ->> 'id' <> old.id then
      raise exception 'resource.id % does not match row id %', new.resource ->> 'id', old.id using errcode = '23514';
    end if;
    new.version_id := old.version_id + 1;
    new.created_at := old.created_at;
    new.created_by := old.created_by;
  end if;

  new.last_updated := now_ts;
  new.updated_by := actor;
  meta := coalesce(new.resource -> 'meta', '{}'::jsonb)
       || jsonb_build_object('versionId', new.version_id::text, 'lastUpdated', fhir.instant(now_ts));
  new.resource := new.resource || jsonb_build_object('id', new.id, 'meta', meta);
  return new;
end;
$$;

-- Copies the superseded (or deleted) version into fhir.resource_history.
create or replace function fhir.record_history()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  insert into fhir.resource_history
    (resource_type, id, version_id, resource, patient_id, last_updated, updated_by, operation)
  values
    (old.resource ->> 'resourceType', old.id, old.version_id, old.resource, old.patient_id,
     old.last_updated, old.updated_by, lower(tg_op));
  return null;
end;
$$;

-- Appends a create/update/delete event to fhir.audit_log.
create or replace function fhir.audit_write()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  act text := case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end;
begin
  if tg_op = 'DELETE' then
    insert into fhir.audit_log
      (action, resource_type, resource_id, patient_id, version_id, actor_id, actor_role, request)
    values
      (act, old.resource ->> 'resourceType', old.id, old.patient_id, old.version_id,
       auth.uid(), fhir.actor_role(), fhir.request_context());
  else
    insert into fhir.audit_log
      (action, resource_type, resource_id, patient_id, version_id, actor_id, actor_role, request)
    values
      (act, new.resource ->> 'resourceType', new.id, new.patient_id, new.version_id,
       auth.uid(), fhir.actor_role(), fhir.request_context());
  end if;
  return null;
end;
$$;


-- -----------------------------------------------------------------------------
-- Errors as FHIR OperationOutcome
-- fhir.fail() raises with a SQLSTATE PostgREST maps to an HTTP status
-- (PT400 -> 400, PT404 -> 404, PT409 -> 409, 42501 -> 403) and puts an
-- OperationOutcome in the error detail, which PostgREST returns as "details".
-- -----------------------------------------------------------------------------
create or replace function fhir.operation_outcome(issue_code text, diagnostics text, severity text default 'error')
returns jsonb
language sql immutable strict parallel safe
set search_path = ''
as $$
  select jsonb_build_object(
    'resourceType', 'OperationOutcome',
    'issue', jsonb_build_array(jsonb_build_object(
      'severity', severity,
      'code', issue_code,
      'diagnostics', diagnostics)));
$$;

create or replace function fhir.fail(sqlstate_code text, issue_code text, diagnostics text)
returns void
language plpgsql
set search_path = ''
as $$
begin
  raise exception using
    message = diagnostics,
    errcode = sqlstate_code,
    detail = fhir.operation_outcome(issue_code, diagnostics)::text;
end;
$$;

grant execute on function
  fhir.operation_outcome(text, text, text),
  fhir.fail(text, text, text)
to authenticated, service_role;

-- =============================================================================
-- supabase-fhir | 0002 access model
-- Who can see which Patient compartment.
--
--   * admins       -> JWT app_metadata.fhir_role = 'admin' (set server side, never by the user)
--   * everyone else -> explicit rows in fhir.patient_access (read or write, optionally time-boxed)
--   * service_role -> bypasses RLS (backend jobs, seeding)
--   * anon         -> no access at all
-- =============================================================================

create table fhir.patient_access (
  id           bigint generated always as identity primary key,
  user_id      uuid not null references auth.users (id) on delete cascade,
  patient_id   text not null,
  access_level text not null default 'read'
               constraint patient_access_level check (access_level in ('read', 'write')),
  valid_from   timestamptz not null default now(),
  valid_until  timestamptz
               constraint patient_access_validity check (valid_until is null or valid_until > valid_from),
  granted_by   uuid default auth.uid(),
  reason       text,
  created_at   timestamptz not null default now(),
  constraint patient_access_unique unique (user_id, patient_id)
);
comment on table fhir.patient_access is
  'Grants a user read or write access to one Patient compartment. A patient portal user gets a row for their own Patient; a clinician gets one per patient in their care.';
create index patient_access_patient_idx on fhir.patient_access (patient_id);

-- True when the JWT carries app_metadata.fhir_role = 'admin'.
create or replace function fhir.is_admin()
returns boolean
language sql stable parallel safe
set search_path = ''
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'fhir_role') = 'admin', false);
$$;

-- Patient ids the current user may read (level = 'read') or write (level = 'write').
-- SECURITY DEFINER so policies do not recurse into patient_access RLS.
create or replace function fhir.accessible_patients(level text default 'read')
returns setof text
language sql stable security definer
set search_path = ''
as $$
  select a.patient_id
  from fhir.patient_access a
  where a.user_id = (select auth.uid())
    and a.valid_from <= now()
    and (a.valid_until is null or a.valid_until > now())
    and (level = 'read' or a.access_level = 'write');
$$;

-- Convenience predicate for custom policies and application checks.
create or replace function fhir.has_patient_access(patient_id text, level text default 'read')
returns boolean
language sql stable
set search_path = ''
as $$
  select fhir.is_admin() or $1 in (select fhir.accessible_patients($2));
$$;

revoke execute on function fhir.accessible_patients(text) from public, anon;
grant execute on function
  fhir.is_admin(),
  fhir.accessible_patients(text),
  fhir.has_patient_access(text, text)
to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Policies
-- -----------------------------------------------------------------------------
alter table fhir.patient_access enable row level security;

create policy "users read their own grants" on fhir.patient_access
  for select to authenticated
  using (user_id = (select auth.uid()) or (select fhir.is_admin()));

create policy "admins manage grants" on fhir.patient_access
  for all to authenticated
  using ((select fhir.is_admin()))
  with check ((select fhir.is_admin()));

grant select, insert, update, delete on fhir.patient_access to authenticated, service_role;

create policy "history visible within compartment" on fhir.resource_history
  for select to authenticated
  using ((select fhir.is_admin()) or patient_id in (select fhir.accessible_patients('read')));

create policy "audit log visible to admins" on fhir.audit_log
  for select to authenticated
  using ((select fhir.is_admin()));

-- -----------------------------------------------------------------------------
-- Every change to a grant is itself audited: who had access to whom, and when.
-- -----------------------------------------------------------------------------
create or replace function fhir.audit_access_change()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    insert into fhir.audit_log (action, resource_type, resource_id, patient_id, actor_id, actor_role, request)
    values ('revoke', 'PatientAccess', old.id::text, old.patient_id, auth.uid(), fhir.actor_role(),
            fhir.request_context() || jsonb_build_object('before', to_jsonb(old)));
  elsif tg_op = 'UPDATE' then
    insert into fhir.audit_log (action, resource_type, resource_id, patient_id, actor_id, actor_role, request)
    values ('grant_change', 'PatientAccess', new.id::text, new.patient_id, auth.uid(), fhir.actor_role(),
            fhir.request_context() || jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
  else
    insert into fhir.audit_log (action, resource_type, resource_id, patient_id, actor_id, actor_role, request)
    values ('grant', 'PatientAccess', new.id::text, new.patient_id, auth.uid(), fhir.actor_role(),
            fhir.request_context() || jsonb_build_object('after', to_jsonb(new)));
  end if;
  return null;
end;
$$;

create trigger fhir_audit_access_change
  after insert or update or delete on fhir.patient_access
  for each row execute function fhir.audit_access_change();

-- =============================================================================
-- supabase-fhir | 0003 define_resource
-- One call creates everything a resource type needs:
--
--   select fhir.define_resource('Device');            -- patient-scoped (default)
--   select fhir.define_resource('Organization', false); -- reference data, readable by all users
--
-- Table layout (fhir.<snake_case_type>):
--   id            FHIR id (text, uuid by default)
--   version_id    increments on every update
--   last_updated  stamped on every write
--   resource      the full FHIR JSON
--   patient_id    generated: the Patient compartment this row belongs to
--   created_at / created_by / updated_by
-- Plus indexes, triggers (versioning, history, audit), RLS policies and grants.
-- Idempotent: safe to re-run to refresh triggers and policies.
-- =============================================================================

create or replace function fhir.define_resource(p_resource_type text, p_compartment boolean default true)
returns text
language plpgsql
set search_path = ''
set client_min_messages to warning
as $fn$
declare
  tbl text;
  pol text;
begin
  if p_resource_type !~ '^[A-Z][A-Za-z]{1,63}$' then
    raise exception 'invalid FHIR resource type: %', p_resource_type using errcode = '22023';
  end if;
  tbl := fhir.table_name(p_resource_type);

  execute format($sql$
    create table if not exists fhir.%1$I (
      id            text primary key default gen_random_uuid()::text
                    constraint %3$I check (id ~ '^[A-Za-z0-9\-\.]{1,64}$'),
      version_id    integer not null default 1,
      last_updated  timestamptz not null default now(),
      resource      jsonb not null
                    constraint %4$I check (resource ->> 'resourceType' = %2$L),
      patient_id    text generated always as (fhir.compartment_patient_id(resource)) stored,
      created_at    timestamptz not null default now(),
      created_by    uuid,
      updated_by    uuid,
      constraint %5$I check (resource ->> 'id' = id)
    )$sql$,
    tbl, p_resource_type, tbl || '_id_format', tbl || '_resource_type', tbl || '_id_sync');

  execute format('comment on table fhir.%I is %L', tbl, 'FHIR ' || p_resource_type || ' resources');

  execute format('create index if not exists %I on fhir.%I (patient_id)', tbl || '_patient_id_idx', tbl);
  execute format('create index if not exists %I on fhir.%I (last_updated desc)', tbl || '_last_updated_idx', tbl);
  execute format('create index if not exists %I on fhir.%I using gin (resource jsonb_path_ops)', tbl || '_resource_idx', tbl);

  execute format('drop trigger if exists fhir_before_write on fhir.%I', tbl);
  execute format('create trigger fhir_before_write before insert or update on fhir.%I for each row execute function fhir.before_write()', tbl);
  execute format('drop trigger if exists fhir_record_history on fhir.%I', tbl);
  execute format('create trigger fhir_record_history after update or delete on fhir.%I for each row execute function fhir.record_history()', tbl);
  execute format('drop trigger if exists fhir_audit_write on fhir.%I', tbl);
  execute format('create trigger fhir_audit_write after insert or update or delete on fhir.%I for each row execute function fhir.audit_write()', tbl);

  execute format('alter table fhir.%I enable row level security', tbl);
  foreach pol in array array['fhir_select', 'fhir_insert', 'fhir_update', 'fhir_delete'] loop
    execute format('drop policy if exists %I on fhir.%I', pol, tbl);
  end loop;

  if p_compartment then
    execute format($sql$
      create policy fhir_select on fhir.%I for select to authenticated
        using ((select fhir.is_admin()) or patient_id in (select fhir.accessible_patients('read')))$sql$, tbl);
    execute format($sql$
      create policy fhir_insert on fhir.%I for insert to authenticated
        with check ((select fhir.is_admin()) or patient_id in (select fhir.accessible_patients('write')))$sql$, tbl);
    execute format($sql$
      create policy fhir_update on fhir.%I for update to authenticated
        using ((select fhir.is_admin()) or patient_id in (select fhir.accessible_patients('write')))
        with check ((select fhir.is_admin()) or patient_id in (select fhir.accessible_patients('write')))$sql$, tbl);
    execute format($sql$
      create policy fhir_delete on fhir.%I for delete to authenticated
        using ((select fhir.is_admin()) or patient_id in (select fhir.accessible_patients('write')))$sql$, tbl);
  else
    execute format($sql$
      create policy fhir_select on fhir.%I for select to authenticated using (true)$sql$, tbl);
    execute format($sql$
      create policy fhir_insert on fhir.%I for insert to authenticated with check ((select fhir.is_admin()))$sql$, tbl);
    execute format($sql$
      create policy fhir_update on fhir.%I for update to authenticated
        using ((select fhir.is_admin())) with check ((select fhir.is_admin()))$sql$, tbl);
    execute format($sql$
      create policy fhir_delete on fhir.%I for delete to authenticated using ((select fhir.is_admin()))$sql$, tbl);
  end if;

  execute format('grant select, insert, update, delete on fhir.%I to authenticated, service_role', tbl);

  insert into fhir.resource_type (resource_type, table_name, compartment)
  values (p_resource_type, tbl, p_compartment)
  on conflict (resource_type) do update set compartment = excluded.compartment;

  return tbl;
end;
$fn$;

revoke execute on function fhir.define_resource(text, boolean) from public;

-- =============================================================================
-- supabase-fhir | 0004 resource tables
-- The US Core / Synthea set. Add your own with fhir.define_resource().
-- Generated search columns mirror the most used FHIR search parameters so
-- PostgREST filters hit an index instead of parsing JSON.
-- =============================================================================

-- Reference data (not scoped to a patient, readable by every signed-in user)
select fhir.define_resource('Practitioner', false);
select fhir.define_resource('PractitionerRole', false);
select fhir.define_resource('Organization', false);
select fhir.define_resource('Location', false);
select fhir.define_resource('Medication', false);

-- Patient compartment
select fhir.define_resource('Patient');
select fhir.define_resource('Encounter');
select fhir.define_resource('Condition');
select fhir.define_resource('Observation');
select fhir.define_resource('Procedure');
select fhir.define_resource('MedicationRequest');
select fhir.define_resource('MedicationAdministration');
select fhir.define_resource('Immunization');
select fhir.define_resource('AllergyIntolerance');
select fhir.define_resource('DiagnosticReport');
select fhir.define_resource('DocumentReference');
select fhir.define_resource('CarePlan');
select fhir.define_resource('CareTeam');
select fhir.define_resource('Goal');
select fhir.define_resource('Device');
select fhir.define_resource('ImagingStudy');
select fhir.define_resource('SupplyDelivery');
select fhir.define_resource('Coverage');
select fhir.define_resource('Claim');
select fhir.define_resource('ExplanationOfBenefit');
select fhir.define_resource('Provenance');

-- Deleting a Patient removes its grants (cascade) and orphans its clinical resources,
-- so only admins may do it. Clinicians with write access still update demographics.
drop policy fhir_delete on fhir.patient;
create policy fhir_delete on fhir.patient
  for delete to authenticated
  using ((select fhir.is_admin()));

-- Access grants point at real patients and disappear with them.
alter table fhir.patient_access
  add constraint patient_access_patient_fk
  foreign key (patient_id) references fhir.patient (id) on delete cascade;

-- -----------------------------------------------------------------------------
-- Search columns
-- -----------------------------------------------------------------------------
alter table fhir.patient
  add column family_name text generated always as (resource #>> '{name,0,family}') stored,
  add column birth_date  date generated always as (fhir.parse_date(resource ->> 'birthDate')) stored,
  add column gender      text generated always as (resource ->> 'gender') stored,
  add column active      boolean generated always as (
    case when resource ->> 'active' in ('true', 'false') then (resource ->> 'active')::boolean else true end) stored;
create index patient_family_name_idx on fhir.patient (family_name);
create index patient_birth_date_idx on fhir.patient (birth_date);

alter table fhir.practitioner
  add column family_name text generated always as (resource #>> '{name,0,family}') stored;

alter table fhir.organization
  add column name text generated always as (resource ->> 'name') stored;

alter table fhir.location
  add column name text generated always as (resource ->> 'name') stored;

alter table fhir.encounter
  add column status       text generated always as (resource ->> 'status') stored,
  add column class_code   text generated always as (resource #>> '{class,code}') stored,
  add column type_code    text generated always as (resource #>> '{type,0,coding,0,code}') stored,
  add column period_start timestamptz generated always as (fhir.parse_datetime(resource #>> '{period,start}')) stored,
  add column period_end   timestamptz generated always as (fhir.parse_datetime(resource #>> '{period,end}')) stored;
create index encounter_period_start_idx on fhir.encounter (patient_id, period_start desc);

alter table fhir.condition
  add column clinical_status     text generated always as (resource #>> '{clinicalStatus,coding,0,code}') stored,
  add column verification_status text generated always as (resource #>> '{verificationStatus,coding,0,code}') stored,
  add column code                text generated always as (resource #>> '{code,coding,0,code}') stored,
  add column code_system         text generated always as (resource #>> '{code,coding,0,system}') stored,
  add column onset_at            timestamptz generated always as (fhir.parse_datetime(resource ->> 'onsetDateTime')) stored,
  add column abatement_at        timestamptz generated always as (fhir.parse_datetime(resource ->> 'abatementDateTime')) stored,
  add column encounter_id        text generated always as (fhir.reference_id(resource #>> '{encounter,reference}', 'Encounter')) stored;
create index condition_code_idx on fhir.condition (code);
create index condition_encounter_idx on fhir.condition (encounter_id);

alter table fhir.observation
  add column status         text generated always as (resource ->> 'status') stored,
  add column category_code  text generated always as (resource #>> '{category,0,coding,0,code}') stored,
  add column code           text generated always as (resource #>> '{code,coding,0,code}') stored,
  add column code_system    text generated always as (resource #>> '{code,coding,0,system}') stored,
  add column effective_at   timestamptz generated always as (fhir.parse_datetime(coalesce(
                              resource ->> 'effectiveDateTime',
                              resource #>> '{effectivePeriod,start}',
                              resource ->> 'effectiveInstant'))) stored,
  add column value_quantity numeric generated always as (
    case when jsonb_typeof(resource #> '{valueQuantity,value}') = 'number'
         then (resource #> '{valueQuantity,value}')::numeric end) stored,
  add column value_unit     text generated always as (resource #>> '{valueQuantity,unit}') stored,
  add column encounter_id   text generated always as (fhir.reference_id(resource #>> '{encounter,reference}', 'Encounter')) stored;
create index observation_code_idx on fhir.observation (patient_id, code, effective_at desc);
create index observation_encounter_idx on fhir.observation (encounter_id);
create index observation_category_idx on fhir.observation (category_code);

alter table fhir.procedure
  add column status       text generated always as (resource ->> 'status') stored,
  add column code         text generated always as (resource #>> '{code,coding,0,code}') stored,
  add column performed_at timestamptz generated always as (fhir.parse_datetime(coalesce(
                            resource ->> 'performedDateTime',
                            resource #>> '{performedPeriod,start}'))) stored,
  add column encounter_id text generated always as (fhir.reference_id(resource #>> '{encounter,reference}', 'Encounter')) stored;
create index procedure_code_idx on fhir.procedure (code);
create index procedure_encounter_idx on fhir.procedure (encounter_id);

alter table fhir.medication_request
  add column status          text generated always as (resource ->> 'status') stored,
  add column intent          text generated always as (resource ->> 'intent') stored,
  add column medication_code text generated always as (resource #>> '{medicationCodeableConcept,coding,0,code}') stored,
  add column authored_on     timestamptz generated always as (fhir.parse_datetime(resource ->> 'authoredOn')) stored,
  add column encounter_id    text generated always as (fhir.reference_id(resource #>> '{encounter,reference}', 'Encounter')) stored;
create index medication_request_status_idx on fhir.medication_request (patient_id, status);

alter table fhir.medication_administration
  add column status          text generated always as (resource ->> 'status') stored,
  add column medication_code text generated always as (resource #>> '{medicationCodeableConcept,coding,0,code}') stored,
  add column effective_at    timestamptz generated always as (fhir.parse_datetime(coalesce(
                               resource ->> 'effectiveDateTime',
                               resource #>> '{effectivePeriod,start}'))) stored;

